local GrainHopperMaker = {}
local PRODUCTS = {
    iron_grain_hopper = { name = "Železni ličnik za žito", ironCost = 2, woodCost = 3, leatherCost = 1, time = 5, cost = 155, prestige = 3, happiness = 2, description = "Železni ličnik za prenos žita." },
    bronze_grain_hopper = { name = "Bronast ličnik za žito", bronzeCost = 2, ironCost = 1, woodCost = 3, leatherCost = 1, time = 7, cost = 380, prestige = 5, happiness = 3, description = "Bronast ličnik za mline." },
    silver_grain_hopper = { name = "Srebrni ličnik za žito", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 11, cost = 920, prestige = 10, happiness = 4, description = "Srebrni ličnik za plemiške mline." },
    gilded_grain_hopper = { name = "Pozlačeni ličnik za žito", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 15, cost = 1980, prestige = 19, happiness = 5, description = "Pozlačeni ličnik za dvorne mline." },
    jewel_set_grain_hopper = { name = "Draguljasti ličnik za žito", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 19, cost = 4280, prestige = 35, happiness = 7, description = "Draguljasti ličnik za kraljeve mline." },
    royal_sovereign_grain_hopper = { name = "Kraljevski suvereni ličnik za žito", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 26, cost = 9200, prestige = 67, happiness = 13, description = "Suvereni ličnik z biseri za krono." },
}
local BUILDINGS = {
    grainhopper_workshop = { name = "Ličniška delavnica", cost = { gold = 315, wood = 185, stone = 125, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    grainhopper_house = { name = "Ličniška hiša", cost = { gold = 1165, wood = 365, stone = 265, silver = 7, iron = 7 }, upkeep = 24, qualityBonus = 18 },
    master_grainhopper_atelier = { name = "Mojstrski ličniški atelje", cost = { gold = 2935, wood = 420, stone = 510, silver = 34, gold = 7 }, upkeep = 69, qualityBonus = 30 },
    sovereign_grainhopper_palace = { name = "Suverena ličniška palača", cost = { gold = 12780, wood = 640, stone = 820, gold = 82, jewel = 19 }, upkeep = 251, qualityBonus = 55, prestigeBonus = 50 },
}
GrainHopperMaker.ironStock = 12; GrainHopperMaker.bronzeStock = 10; GrainHopperMaker.woodStock = 18; GrainHopperMaker.leatherStock = 10; GrainHopperMaker.silverStock = 8; GrainHopperMaker.goldStock = 6; GrainHopperMaker.jewelStock = 4; GrainHopperMaker.pearlStock = 4
GrainHopperMaker.productStock = {}; GrainHopperMaker.buildings = {}; GrainHopperMaker.maker = nil; GrainHopperMaker.activeMaking = {}; GrainHopperMaker.totalProducts = 0; GrainHopperMaker.dayTimer = 0
function GrainHopperMaker.init() GrainHopperMaker.ironStock=12; GrainHopperMaker.bronzeStock=10; GrainHopperMaker.woodStock=18; GrainHopperMaker.leatherStock=10; GrainHopperMaker.silverStock=8; GrainHopperMaker.goldStock=6; GrainHopperMaker.jewelStock=4; GrainHopperMaker.pearlStock=4; GrainHopperMaker.productStock={}; GrainHopperMaker.buildings={}; GrainHopperMaker.maker=nil; GrainHopperMaker.activeMaking={}; GrainHopperMaker.totalProducts=0; GrainHopperMaker.dayTimer=0; print("[GrainHopperMaker] Royal Grain Hopper Maker System initialized (6 products, 4 buildings)") end
function GrainHopperMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainHopperMaker.maker={name=n or ("Ličnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ličnikar najet: %s (spretnost: %d)",GrainHopperMaker.maker.name,s),"success") end; return true end
function GrainHopperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainHopperMaker.build(id) local ok,e=GrainHopperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainHopperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainHopperMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainHopperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainHopperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GrainHopperMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GrainHopperMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GrainHopperMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GrainHopperMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GrainHopperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainHopperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainHopperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainHopperMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainHopperMaker.buildings==0 then return false,"Potrebna ličniška delavnica" end; if not GrainHopperMaker.maker then return false,"Potreben ličnikar" end; return true end
function GrainHopperMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainHopperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GrainHopperMaker.ironStock=GrainHopperMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GrainHopperMaker.bronzeStock=GrainHopperMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GrainHopperMaker.woodStock=GrainHopperMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GrainHopperMaker.leatherStock=GrainHopperMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GrainHopperMaker.silverStock=GrainHopperMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainHopperMaker.goldStock=GrainHopperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainHopperMaker.jewelStock=GrainHopperMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainHopperMaker.pearlStock=GrainHopperMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainHopperMaker.maker then t=math.max(1,t-math.floor(GrainHopperMaker.maker.skill/13)) end; table.insert(GrainHopperMaker.activeMaking,{id="grainhopper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainHopperMaker.completeMaking(m) local q=1.0+(GrainHopperMaker.getQualityBonus()/100); if GrainHopperMaker.maker then q=q+(GrainHopperMaker.maker.skill/140) end; q=math.min(2.5,q); GrainHopperMaker.productStock[m.productType]=(GrainHopperMaker.productStock[m.productType] or 0)+m.quantity; GrainHopperMaker.totalProducts=GrainHopperMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainHopperMaker.maker then GrainHopperMaker.maker.itemsMade=GrainHopperMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainHopperMaker.maker.skill=math.min(100,GrainHopperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ličnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grainhopper.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GrainHopperMaker.update(dt) if not _G.state then return end; GrainHopperMaker.dayTimer=GrainHopperMaker.dayTimer+dt; if GrainHopperMaker.dayTimer>=30 then GrainHopperMaker.dayTimer=0; for i=#GrainHopperMaker.activeMaking,1,-1 do local m=GrainHopperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainHopperMaker.completeMaking(m); table.remove(GrainHopperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainHopperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainHopperMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainHopperMaker.getStats() return {ironStock=GrainHopperMaker.ironStock,bronzeStock=GrainHopperMaker.bronzeStock,woodStock=GrainHopperMaker.woodStock,leatherStock=GrainHopperMaker.leatherStock,silverStock=GrainHopperMaker.silverStock,goldStock=GrainHopperMaker.goldStock,jewelStock=GrainHopperMaker.jewelStock,pearlStock=GrainHopperMaker.pearlStock,productStock=GrainHopperMaker.productStock,numBuildings=#GrainHopperMaker.buildings,hasMaker=GrainHopperMaker.maker~=nil,makerName=GrainHopperMaker.maker and GrainHopperMaker.maker.name or "—",makerSkill=GrainHopperMaker.maker and GrainHopperMaker.maker.skill or 0,activeMaking=#GrainHopperMaker.activeMaking,totalProducts=GrainHopperMaker.totalProducts} end
return GrainHopperMaker
